    const id=norm(r.employeeId),name=norm(r.name),unit=norm(r.unit);
    if(!id||!name||!unit)r._identityIssue='ID, nama, atau outlet belum lengkap';
    else if((idNames.get(id)||new Set()).size>1)r._identityIssue='ID dipakai oleh beberapa nama';
